import{C as r,b as x,c as p}from"./dom-6kYVTdCz.js";import{b as I,c as i,t}from"./header-CxiiZK_8.js";const N={"si.character.awareness.why":"the record is vivid, the recording invisible: the archive reads as the world","si.character.control.why":"deliberate and methodical — it resists being hurried, not being steered","si.character.endurance.why":"the marathon register — checklists and rituals run all day at near-zero cost","si.character.precision.why":"the psyche's proofreader: deviations named to the shade and the semitone","si.character.speed.why":"nothing is answered until the record has been consulted","si.energy.recovery.auxiliary":"Quick, once the procedure is handed over and confirmed done.","si.energy.recovery.dominant":"Refills during use — a day that matches the record barely costs.","si.energy.recovery.inferior":"The hangover shelf: ~30 min of global dim while the symptom-checking winds down.","si.energy.recovery.shadow":"Incomplete — entries written here stay open; some charge does not return today.","si.energy.recovery.tertiary":"Slower: the ritual restores only if it is actually kept.","si.feeder.fe":{figure:"The feeds spread across the whole ledger.",mechanism:"Fe — extraverted feeling — hands the record people: who takes their coffee how, whose mother is ill, what this family does on the first snow. Care, distributed, and deviation detection turned interpersonal — the first to notice a friend is not okay is usually this coupling, comparing today's voice against years of stored Tuesdays.",pair:"the ISFJ · ESFJ coupling",provenance:"myers"},"si.feeder.fi":{figure:"Nothing new is admitted at the intake; the same few strata brighten from within while the rest dim.",mechanism:"The ISTJ loop, with Te cut out: Fi — introverted feeling — supplies the verdicts now, from inside. Entries are re-read for how they felt, and the wounded ones get fed nightly. The one thing that would break the pattern is an outside result — which is exactly what the loop no longer requests.",pair:"the ISTJ Si–Fi loop",provenance:"community",warn:"Loop coupling: introverted judging feeding introverted perception — no correction from outside."},"si.feeder.ne":{figure:"The pool dims and lays down provisional bands for futures that never arrive to feed them.",mechanism:"Ne — extraverted intuition — floods the intake with hypotheticals: things that might happen, could be true, would be interesting. None of it will ever match the record, because none of it has happened — both functions gather and neither judges. In a real stack these two alternate through a judge; wired directly, the archive fills with fiction.",pair:"perception feeding perception",provenance:"myers",warn:"Unstable coupling: perception feeding perception, with nothing judging either."},"si.feeder.te":{figure:"Watch the audit sweep cross the record on a schedule.",mechanism:"Te — extraverted thinking — hands the record verified results: what was measured, what shipped, what the procedure actually produced. The archive becomes institutional — numbered, dated, reproducible — and deviations get escalated instead of endured. The coupling that runs infrastructure: a record trusted because something outside it keeps checking.",pair:"the ISTJ · ESTJ coupling",provenance:"myers"},"si.feeder.ti":{figure:"The same entries re-proven from inside, the rim closed.",mechanism:"The ISFJ loop, with Fe cut out: Ti — introverted thinking — supplies private logic for why the record must be right. Every remembered procedure is re-derived into a rule, every rule defended as principle: internally consistent, socially unchecked — and the person the rules were for has left the room.",pair:"the ISFJ Si–Ti loop",provenance:"community",warn:"Loop coupling: introverted judging feeding introverted perception — no correction from outside."},"si.fieldNotes.mirror":{figure:"One is water that keeps; the other is water that looks.",mechanismHtml:"Same element, opposite attitude — and the difference is what happens to the moment. <strong>Si</strong> banks it: metered intake, every arrival compared against every layer ever laid down — the world as a place to recognise. <strong>Se</strong> rides it: full resolution, zero lag, nothing kept — the world as a place to act. Si trades the moment for a record no moment can take away; Se trades the record for the moment itself.",provenance:"jung"},"si.fieldNotes.vignette.afraidOfChange":{figure:"The record is a price list.",kind:"the accusation",mechanism:'What the accusation misses is that the record is doing cost accounting. Si remembers what the last "improvement" actually cost — the migration that lost the invoices, the reorg that lost three people — at a resolution the person proposing the next one does not have. The tell that it is not timidity: bring evidence of the tested kind, a pilot, a precedent, a rollback plan, and Si moves — reluctantly, then durably. What it resists is not the new; it is the unpriced.',provenance:"community",title:`"You're Just Afraid of Change"`},"si.fieldNotes.vignette.ballast":{figure:"A small set of physical constants, fiercely defended.",kind:"as a tertiary",mechanism:"Tertiary Si in an INTP or INFP: the archive as ballast under a theory-lab. The same tea in the same mug, the same walking route at the same hour, the same album for the same mood — an anchor that keeps a possibility-driven mind moored somewhere. It looks like mere habit until travel disrupts it, and the week's thinking quietly degrades with the routine.",provenance:"grant",title:"The Ballast"},"si.fieldNotes.vignette.grip":{figure:"The archive floods open, all at once.",kind:"the grip",mechanism:"An ENTP past the end of their reserves stops generating futures and floods into inferior Si — suddenly certain the mole is cancer, re-living a decade-old embarrassment at full resolution, gripped by the body's every signal. Not a personality change: a low-capacity seat taking a dominant-sized flood.",provenance:"quenk",title:"The Grip"},"si.fieldNotes.vignette.hum":{figure:"The ring lights, or it doesn't.",kind:"field sighting",mechanism:"The machine sounds wrong. Nobody else in the shop hears it — the gauges all read normal — but an ISTJ who has stood beside it for nine years has already shut it down. The failing bearing gets found on the bench. Asked how they knew, they say it did not sound like itself: a complete technical explanation from inside the archive, and no explanation at all from outside it.",provenance:"community",title:"The Hum"},"si.fieldNotes.vignette.loop":{figure:"The same strata, fed nightly.",kind:"the loop",mechanism:"An ISTJ under stress pairs dominant Si with tertiary Fi: the record turns inward and starts serving grievances — every slight on file, re-read nightly with the emotional charge refreshed. Te's outside audit is the function the loop avoids. The archive has never been more detailed, or less useful.",provenance:"community",title:"The Loop"},"si.fieldNotes.vignette.noImagination":{figure:"Imagination pointed backward, at archival resolution.",kind:"the misread",mechanism:"Because Si rarely speculates aloud, it gets filed as unimaginative — which mistakes direction for absence. The imagination runs backward: the kitchen of a childhood house reconstructible down to the latch, a colleague's exact wording from a meeting years closed. Ask a question that points into the record instead of out of it and the detail comes back with a vividness the forward-facing functions cannot touch.",provenance:"community",title:"Mistaken for Having No Imagination"},"si.fieldNotes.vignette.unprecedented":{figure:"The search returns nothing, and the pool dims while it keeps searching.",kind:"the wrong instrument",mechanism:"A comparator needs precedent, and some situations have none: the first day in a country the record has never seen, the market behaving in a way no file matches, the diagnosis nobody rehearsed. Si's first move — consult the archive — comes back empty. This is where the stack's intuitive seat earns its keep, whatever position it holds; the record resumes authority the moment the unprecedented has happened once.",provenance:"community",title:"The Unprecedented"},"si.hero.heading":"The Still Pool of {fn}","si.hero.subtitle":"A sealed pool banded with strata — every past inflow laid down as a ring, the oldest fused bright at the core. Each admitted drop sinks to the layer it matches, and the whole ring lights when past and present agree.","si.hero.tag":"introverted sensing","si.lab.btn.accept.label":"Accept","si.lab.btn.accept.sub":"the new normal — lay a sub-band","si.lab.btn.deviant.label":"The Familiar, Changed","si.lab.btn.deviant.sub":"a 90% match — something is off","si.lab.btn.familiar.label":"The Familiar, On Time","si.lab.btn.familiar.sub":"the morning ritual arrives as always","si.lab.btn.novel.label":"The Unprecedented","si.lab.btn.novel.sub":"nothing in the record matches this","si.lab.btn.reject.label":"Dismiss","si.lab.btn.reject.sub":"an anomaly — expel the drop","si.lab.meter.pleasure":"Recognition Pleasure","si.lab.meter.stress":"Stress","si.lab.narration.deviant":{figure:"The strobe is the other ten percent: stored colour against observed colour, beating like a flat note.",mechanism:"It reached its ring and refused to merge — a ninety percent match. Si's alarm is never vague: something is off, and it knows exactly what. The record is waiting for your ruling.",provenance:"currents"},"si.lab.narration.deviantAccept":{figure:"A new band forms beside the old one — thin, dim, provisional — and stays dim until repetition feeds it.",mechanism:"Accepted. This is how Si actually changes: not never, and not lightly, but by laying the new normal down next to the old record and waiting for evidence. Change is possible here. It is just never free.",provenance:"currents"},"si.lab.narration.deviantAuto":{figure:"The pool ruled for itself, and settled.",mechanism:"Left unruled, a settled archive defaults to its own record — not stubbornness; the prior doing its job. But notice that the ruling happened either way: an open dispute with the record is the one state Si cannot hold.",provenance:"currents"},"si.lab.narration.deviantReject":{figure:"The drop is expelled back through the rim, and the original stratum re-asserts a shade brighter.",mechanism:"Dismissed. A record does not just survive an anomaly — it is confirmed by one. Note what vigilance costs, though: every alarm rehearsed makes the next one slightly easier to raise.",provenance:"currents"},"si.lab.narration.familiar":{figure:"The drop goes straight down — no search, no negotiation — and the whole ring lights on contact.",mechanism:"The morning ritual arrives on schedule and is recognised instantly: not a lookup but a resonance, and it costs almost nothing. Watch the encounter cost readout as the ritual repeats.",provenance:"currents"},"si.lab.narration.familiar2":{figure:"The stratum thickens a little with each pass.",mechanism:"Fed again, a little cheaper than last time. This is what ritual is for: each repetition drops the price of tomorrow's match. From outside it looks like rigidity. From inside it is load-bearing — the fixed points that make the rest of the day affordable.",provenance:"currents"},"si.lab.narration.hoverCoarse":"You are sounding the pool. Each ring under the finger reports its record — what it holds, how often it has been fed, how bright it still runs. The deep centre is the oldest material in the psyche: first rooms, first foods, first safety. It does not dim.","si.lab.narration.hoverFine":"You are sounding the pool. Each ring under the cursor reports its record — what it holds, how often it has been fed, how bright it still runs. The deep centre is the oldest material in the psyche: first rooms, first foods, first safety. It does not dim.","si.lab.narration.intro":"The pool runs unattended: metered drops arriving one at a time, each interrogated by the depths — matched, flagged, or filed as new. Spawn an arrival and watch the meters answer; when the record disputes one, the ruling is yours.","si.lab.narration.introHintCoarse":"Press and hold a ring to sound what each ring keeps.","si.lab.narration.introHintFine":"Hover the strata to sound what each ring keeps.","si.lab.narration.novel":{figure:"Ring after ring dims as the search passes; the pool contracts a shade.",mechanism:"No stratum answers, and the whole system runs the flinch of being asked to file something it has never seen. Nothing here is dramatic; the stress climbs slowly. Novelty is not a catastrophe for Si. It is a cost.",provenance:"currents"},"si.lab.narration.novel2":{figure:"A provisional band settles at the rim, thin and dim — the first layer of a future familiarity.",mechanism:"Spawn it again and watch the price fall; by the third arrival it will have a home that answers. Nothing is comfortable the first time. Almost anything can become comfortable.",provenance:"currents"},"si.lab.resolveAria":"Ruling on the pending deviation","si.lab.state.alarm":"Discrepancy Alarm","si.lab.state.equilibrium":"Still Water","si.lab.state.misfile":"Mis-filed","si.lab.state.settled":"Settled Resonance","si.lab.state.unmoored":"Unprecedented Input","si.lab.telemetry.cogState":"Cognitive state","si.lab.telemetry.cost":"Encounter cost","si.lab.telemetry.crossHead":"cross-listen · the same arrivals, reaching Se","si.lab.telemetry.match":"Live match","si.lab.telemetry.sibPleasure":"Se pleasure","si.lab.telemetry.sibStress":"Se stress","si.lab.telemetry.visitSe":"visit Se →","si.meta.title":"Si — Introverted Sensing · CURRENTS","si.slot.auxiliary":{example:"An ESTJ pulls the procedure that worked in 2019, adjusts two lines, and ships it by noon.",figure:"A four-fifths pool, indexed for retrieval.",mechanism:"In the second seat, the archive serves an agenda: precedent, procedure, and the known-good way are supplied on demand to a dominant judging function that acts on them. Less identity than a first seat, more utility — the record is a tool here, not a home.",provenance:"myers"},"si.slot.critical":{example:'An ISFP hears "you always do this" in their own voice, with three dated examples attached.',figure:"Old entries lit in accusation, the good cases left dark.",mechanism:"In the sixth seat, the record turns on the self as a registrar with a grudge: you always do this, it went wrong last time too, remember. Precise citations, hostile filing, and no interest in the cases that went well.",provenance:"beebe"},"si.slot.demon":{example:"At the bottom of a bad month, an INFJ reads their whole past as one unbroken file of failure.",figure:"The strata reordered into a case for the prosecution.",mechanism:"The eighth seat runs rarest and worst. When it erupts, the past is weaponised against the self: an inventory of every old failure presented as the permanent record — immune to context, indifferent to growth, formatted as fact. It is the least practised seat in the stack, not a verdict.",provenance:"beebe"},"si.slot.dominant":{example:"The machine sounds a third low; an ISTJ has already shut it down while the gauges still read normal.",figure:"CURRENTS draws this as a banded pool — the deepest archive in the psyche, every ring a year.",mechanism:"In the first seat, the present is read against a deep stored record, and the comparison is instant: same as always, or off. Deviation registers before reasoning does — the hum a third lower, the handshake a shade brief. What the record confirms costs nothing; what contradicts it is felt bodily, like a step where the floor is not where the foot expected it.",provenance:"myers"},"si.slot.inferior":{example:"An ENFP under real depletion checks the same mole four times and re-lives a 2014 apology verbatim.",figure:"A shallow pool that floods without warning.",mechanism:"In the fourth seat, the record lives in a fog: details, dates, and where-things-are arrive late and partial. Under real depletion the archive floods open as symptom-checking and haunting — every bodily signal matched against every remembered illness, every past mistake suddenly present tense. This is Quenk's grip, for a function ignored all day.",provenance:"quenk"},"si.slot.opposing":{example:'Told "we tried that in 2020 and it failed," an ESTP produces a vivid memory of the time it worked.',figure:"Below the waterline, one stratum flares to win a point, then goes dark.",mechanism:"The fifth seat opens the shadow — the four positions a person runs rarely, and mostly without noticing. Here the record wakes as an obstacle-remover: when precedent is used to close a live option, counter-testimony appears — a vivid memory of the time it did work — held exactly long enough to win the point, then dropped.",provenance:"beebe"},"si.slot.tertiary":{example:"An INTP defends the same tea, mug, and walking route with surprising heat — and thinks better for them.",figure:"A small pool, deep in a few rings, visited irregularly.",mechanism:"In the third seat, the archive is a private museum: comfort rituals, remembered rooms, the same meal from the same place — ballast for a life otherwise run on possibility. Under stress it turns curator-in-reverse, replaying old failures at full fidelity. With age it steadies into a continuity the dominant functions cannot supply.",provenance:"grant"},"si.slot.trickster":{example:"An ENFJ repeats last quarter's mistake with total confidence, then vividly recalls a meeting that never happened.",figure:"The index returns the wrong drawer, in perfect handwriting.",mechanism:"In the seventh seat, the archive is a rigged index: either the precedent is missing when needed — the same mistake, made fresh, with total confidence — or a false precedent arrives wearing perfect detail. Neither failure announces itself, which is the trick.",provenance:"beebe"},"si.zoneA.canvasAria":"Interactive visual representation of Introverted Sensing as a still pool seen from above: concentric sediment strata, the oldest fused bright at the core, with metered drops sinking to the ring they match — the whole ring lights when past and present agree, and strobes when the familiar arrives changed. Point at or press a ring to sound what it keeps","si.zoneB.ageNote":"With age, lower stack positions gain fidelity and duty cycle — and the pool itself gains strata and rigidifies.","si.zoneB.heading":"The Eight Faces of Si","si.zoneB.lede":"The canvas draws Si as a banded pool: every arrival compared against the layers of past experience it keeps. Where Si sits in a person's stack — the fixed order their eight functions come in — decides how well that record serves. Click a position to see the change, from the dominant's bedrock archive to the demon's weaponised inventory, and watch the filing errors climb down the stack. Drag the maturity slider to watch the strata multiply and rigidify with age.","si.zoneB.railAria":"Stack positions for Si","si.zoneC.heading":"What Feeds Into Si?","si.zoneC.lede":"Si gathers; it does not judge. Introverted perception is fed by extraverted judgment, so its real partners are Te and Fe — the outer judges that keep the record honest. Click a feeder and watch what the pool learns to keep.","si.zoneC.unstableDefault":"Unstable coupling: perception feeding perception, with nothing judging either.","si.zoneD.canvasAria":"The Si recognition lab: a strata pool that matches familiar arrivals with a ring-wide chime, strobes and posts a diff readout when the familiar arrives changed, and files the unprecedented as a provisional rim band — with accept and dismiss controls for the pending ruling","si.zoneD.heading":"The Recognition Lab","si.zoneD.kicker":"Zone D · the recognition lab","si.zoneD.lede":"Si is a comparator: every arrival is interrogated by the depths — matched, flagged as off-record, or filed as unprecedented. This lab hands you all three arrivals and, when the record disputes one, the ruling. Watch the encounter cost fall as ritual repeats; watch the flinch when nothing answers.","si.zoneE.lede":"Patterns from the wild — how Si shows up in daily life."};I(N);function E(){const a={fn:r("--c-accent"),n:r("--c-n"),s:r("--c-s"),f:r("--c-f"),pos:[r("--pos-1"),r("--pos-2"),r("--pos-3"),r("--pos-4")],sh:r("--pos-sh"),warn:r("--warn"),crit:r("--crit"),ink:r("--ink"),ink2:r("--ink-2"),muted:r("--muted"),grid:r("--grid"),axis:r("--axis"),surface:r("--surface")},s=e=>({name:t(`site.position.${e}.name`),ord:t(`site.position.${e}.ord`)}),m=[{key:"dominant",...s("dominant"),types:"ISTJ · ISFJ",shadow:!1,series:0,params:{scale:1,fidelity:.95,latency:0,noise:0,duty:1,control:1,contrary:0},copy:i("si.slot.dominant")},{key:"auxiliary",...s("auxiliary"),types:"ESTJ · ESFJ",shadow:!1,series:1,params:{scale:.8,fidelity:.85,latency:80,noise:.05,duty:.85,control:.9,contrary:0},copy:i("si.slot.auxiliary")},{key:"tertiary",...s("tertiary"),types:"INTP · INFP",shadow:!1,series:2,params:{scale:.55,fidelity:.6,latency:250,noise:.2,duty:.5,control:.6,contrary:0},copy:i("si.slot.tertiary")},{key:"inferior",...s("inferior"),types:"ENTP · ENFP",shadow:!1,series:3,params:{scale:.4,fidelity:.35,latency:700,noise:.45,duty:.25,control:.35,contrary:.12},copy:i("si.slot.inferior")},{key:"opposing",...s("opposing"),types:"ESTP · ESFP",shadow:!0,series:4,params:{scale:.46,fidelity:.42,latency:600,noise:.5,duty:.45,control:.4,contrary:.25},copy:i("si.slot.opposing")},{key:"critical",...s("critical"),types:"ISTP · ISFP",shadow:!0,series:4,params:{scale:.44,fidelity:.35,latency:900,noise:.55,duty:.35,control:.3,contrary:.35},copy:i("si.slot.critical")},{key:"trickster",...s("trickster"),types:"ENTJ · ENFJ",shadow:!0,series:4,params:{scale:.42,fidelity:.28,latency:1200,noise:.6,duty:.3,control:.2,contrary:.55},copy:i("si.slot.trickster")},{key:"demon",...s("demon"),types:"INTJ · INFJ",shadow:!0,series:4,params:{scale:.4,fidelity:.2,latency:1500,noise:.65,duty:.22,control:.12,contrary:.65},copy:i("si.slot.demon")}],u={endurance:{w:1,why:t("si.character.endurance.why")},precision:{w:.95,why:t("si.character.precision.why")},speed:{w:.48,why:t("si.character.speed.why")},control:{w:.88,why:t("si.character.control.why")},awareness:{w:.75,why:t("si.character.awareness.why")}},f=[{key:"te",name:"Te",color:"#17d4ef",canonical:!0,cfg:{rate:.5,weight:1,variety:.55,audit:!0,aim:3.14},copy:i("si.feeder.te")},{key:"fe",name:"Fe",color:"#f9748f",canonical:!0,cfg:{rate:.62,weight:.9,variety:.95,aim:3},copy:i("si.feeder.fe")},{key:"ne",name:"Ne",color:a.n,canonical:!1,unstable:!0,cfg:{rate:.85,weight:.3,variety:1,starve:!0},copy:i("si.feeder.ne")},{key:"fi",name:"Fi",color:"#f56a8c",canonical:!1,cfg:{rate:.45,weight:.8,sealed:!0,loopRings:[5,6]},copy:i("si.feeder.fi")},{key:"ti",name:"Ti",color:"#4fc9e0",canonical:!1,cfg:{rate:.45,weight:.85,sealed:!0,loopRings:[3,4]},copy:i("si.feeder.ti")}];function g(e){const h=11.2*(e/60),l=e%15/15,d=2.1*Math.max(0,1-Math.abs(l-.08)*6.5);return Math.max(0,h-d)}function y(e){const h=19*Math.pow(e/60,1.22);let l=0;for(const[c,S]of[[14,10],[39,10],[66,12],[95,8]])e>=c&&(l+=S*p((e-c)/1.6,0,1));const d=e<2?0:1.6*Math.sin(e*.7)+1.3*Math.sin(e*2+.9);return p(h+l+d,0,100)}const o=[{key:"dom",label:t("site.position.dominant.name"),color:a.pos[0],f:g},{key:"aux",label:t("site.position.auxiliary.name"),color:a.pos[1],f:e=>20*Math.pow(e/60,1.06)},{key:"tert",label:t("site.position.tertiary.name"),color:a.pos[2],f:e=>29*Math.pow(e/60,1.4)},{key:"inf",label:t("site.position.inferior.name"),color:a.pos[3],f:e=>Math.min(100,84*Math.pow(e/60,1.9))},{key:"sh",label:t("site.position.shadow.name"),color:a.sh,f:y}],w=60*Math.pow(100/84,1/1.9),v=[{label:t("site.position.dominant.name"),v:1,color:a.pos[0],series:0},{label:t("site.position.auxiliary.name"),v:1.5,color:a.pos[1],series:1},{label:t("site.position.tertiary.name"),v:2.5,color:a.pos[2],series:2},{label:t("site.position.inferior.name"),v:4,color:a.pos[3],series:3},{label:t("site.position.shadow.name"),v:4.5,color:a.sh,band:[3,6],series:4}],b=[{label:t("site.position.dominant.name"),color:a.pos[0],note:t("si.energy.recovery.dominant"),f:e=>e<=30?100-o[0].f(e):n(0)+(100-n(0))*(1-Math.exp(-(e-30)/7))},{label:t("site.position.auxiliary.name"),color:a.pos[1],note:t("si.energy.recovery.auxiliary"),f:e=>e<=30?100-o[1].f(e):n(1)+(100-n(1))*(1-Math.exp(-(e-30)/11))},{label:t("site.position.tertiary.name"),color:a.pos[2],note:t("si.energy.recovery.tertiary"),f:e=>e<=30?100-o[2].f(e):n(2)+(100-n(2))*(1-Math.exp(-(e-30)/17))},{label:t("site.position.inferior.name"),color:a.pos[3],note:t("si.energy.recovery.inferior"),f:e=>e<=30?100-o[3].f(e):e<60?n(3):n(3)+(100-n(3))*(1-Math.exp(-(e-60)/21))},{label:t("site.position.shadow.name"),color:a.sh,note:t("si.energy.recovery.shadow"),f:e=>e<=30?100-o[4].f(e):n(4)+(92-n(4))*(1-Math.exp(-(e-30)/26))}];function n(e){return 100-o[e].f(30)}const k={buttons:[{id:"btnFamiliar",key:"familiar",color:a.fn,impact:{stress:-.04,pleasure:.22},followMs:4600},{id:"btnDeviant",key:"deviant",color:a.warn,impact:{stress:.34,pleasure:-.06},followMs:0},{id:"btnNovel",key:"novel",color:a.n,impact:{stress:.22,pleasure:-.02},followMs:6200}],states:{settled:{label:t("si.lab.state.settled"),color:"#17c964"},equilibrium:{label:t("si.lab.state.equilibrium"),color:a.fn},alarm:{label:t("si.lab.state.alarm"),color:a.warn},unmoored:{label:t("si.lab.state.unmoored"),color:a.n},misfile:{label:t("si.lab.state.misfile"),color:a.crit}},sibling:{familiar:{stress:.07,pleasure:-.03},deviant:{stress:-.02,pleasure:.1},novel:{stress:-.03,pleasure:.14}},narrations:{familiar:i("si.lab.narration.familiar"),familiar2:i("si.lab.narration.familiar2"),deviant:i("si.lab.narration.deviant"),deviantAccept:i("si.lab.narration.deviantAccept"),deviantReject:i("si.lab.narration.deviantReject"),deviantAuto:i("si.lab.narration.deviantAuto"),novel:i("si.lab.narration.novel"),novel2:i("si.lab.narration.novel2"),hover:x?t("si.lab.narration.hoverCoarse"):t("si.lab.narration.hoverFine")}},T={mirror:{label:"Si",counterpart:"Se",counterpartColor:"var(--pos-1)",copy:i("si.fieldNotes.mirror")},vignettes:[i("si.fieldNotes.vignette.hum"),i("si.fieldNotes.vignette.loop"),i("si.fieldNotes.vignette.grip"),i("si.fieldNotes.vignette.ballast"),i("si.fieldNotes.vignette.afraidOfChange"),i("si.fieldNotes.vignette.noImagination"),i("si.fieldNotes.vignette.unprecedented")]};return{COL:a,SLOTS:m,CHARACTER:u,FEEDERS:f,SERIES:o,GRIP_T:w,COSTS:v,RECOVERY:b,LAB:k,ZONE_F:T}}export{E as l};
